-- High-stakes controls: level descriptors, stable audio, competency coverage, and dual rating.
create table public.assessment_level_descriptors(language text not null,level text not null,framework text not null,descriptors jsonb not null,limitations text not null,primary key(language,level));
alter table public.assessment_level_descriptors enable row level security;
create policy level_descriptors_public_read on public.assessment_level_descriptors for select using(true);
alter table public.assessment_tasks add column if not exists audio_file_path text;
alter table public.assessment_tasks add column if not exists transcript_release text not null default 'after_submit' check(transcript_release in ('never','after_submit','immediate'));
create table public.assessment_ratings(id uuid primary key default gen_random_uuid(),response_id uuid not null references public.assessment_task_responses(id) on delete cascade,rater_id uuid not null references public.profiles(id),criteria_scores jsonb not null default '{}',total_score numeric not null check(total_score between 0 and 100),feedback text not null,created_at timestamptz not null default now(),unique(response_id,rater_id));
alter table public.assessment_ratings enable row level security;
create policy ratings_staff_read on public.assessment_ratings for select using(public.is_staff());
create policy ratings_rater_insert on public.assessment_ratings for insert with check(rater_id=auth.uid() and public.current_role() in ('instructor','academic','admin','superadmin'));
alter table public.assessment_task_responses drop constraint if exists assessment_task_responses_status_check;
alter table public.assessment_task_responses add constraint assessment_task_responses_status_check check(status in ('pending_review','rated','needs_adjudication','returned'));
create policy assessment_assets_staff_insert on storage.objects for insert to authenticated with check(bucket_id='assessment-assets' and public.current_role() in ('academic','admin','superadmin'));
create policy assessment_assets_staff_read on storage.objects for select to authenticated using(bucket_id='assessment-assets' and public.is_staff());
create or replace view public.assessment_competency_coverage with (security_invoker=true) as select t.id test_id,count(distinct q.competency)::int competency_count,array_agg(distinct q.competency) competencies from public.assessment_tests t left join public.assessment_questions q on q.test_id=t.id group by t.id;
create or replace view public.assessment_quality_summary with (security_invoker=true) as select t.id,t.code,t.language,t.level,t.test_type,t.version,t.review_status,t.validation_status,t.pilot_sample_size,t.reliability,count(distinct q.id)::int question_count,count(distinct k.id)::int task_count,coalesce(b.min_objective_items,20) min_objective_items,coalesce(b.min_tasks,4) min_tasks,count(distinct q.competency)::int competency_count,(count(distinct case when k.skill='listening' then k.id end)=0 or count(distinct case when k.skill='listening' and k.audio_file_path is not null then k.id end)=count(distinct case when k.skill='listening' then k.id end)) audio_ready,(count(distinct q.id)>=coalesce(b.min_objective_items,20) and count(distinct k.id)>=coalesce(b.min_tasks,4) and count(distinct q.competency)>=case when b.min_tasks=0 then 2 else 5 end and (count(distinct case when k.skill='listening' then k.id end)=0 or count(distinct case when k.skill='listening' and k.audio_file_path is not null then k.id end)=count(distinct case when k.skill='listening' then k.id end))) content_complete from public.assessment_tests t left join public.assessment_questions q on q.test_id=t.id left join public.assessment_tasks k on k.test_id=t.id left join public.assessment_blueprints b on b.test_id=t.id group by t.id,b.min_objective_items,b.min_tasks;
