insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('assessment-assets','assessment-assets',false,20971520,array['audio/mpeg','audio/mp4','audio/wav','audio/ogg']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
insert into public.assessment_level_descriptors(language,level,framework,descriptors,limitations) values
('English','A1','CEFR','{"reading":"understands names, familiar words, and very short simple texts","listening":"recognizes familiar words and basic phrases delivered slowly","writing":"produces short basic personal information","speaking":"uses simple memorized expressions with support"}','Not evidence of independent communication in unfamiliar situations.'),
('English','A2','CEFR','{"reading":"understands short predictable everyday texts","listening":"understands high-frequency information on immediate needs","writing":"writes short connected messages on familiar matters","speaking":"handles simple routine exchanges"}','Complex explanations and sustained interaction are outside scope.'),
('English','B1','CEFR','{"reading":"understands straightforward factual texts on familiar interests","listening":"follows clear standard speech on familiar matters","writing":"produces connected text and reasons for opinions","speaking":"manages familiar travel, study, and work situations"}','Nuanced academic or professional performance requires higher evidence.'),
('English','B2','CEFR','{"reading":"understands complex factual and argumentative texts","listening":"follows extended speech with clear organization","writing":"develops a structured argument with relevant detail","speaking":"interacts with fluency and supports viewpoints"}','Specialized high-stakes domains require domain-specific assessment.'),
('English','C1','CEFR','{"reading":"understands demanding texts and implicit meaning","listening":"follows extended discourse even when structure is not explicit","writing":"produces well-structured detailed text with controlled style","speaking":"uses language flexibly for academic and professional purposes"}','C1 does not imply native-like mastery in every domain.'),
('English','C2','CEFR','{"reading":"interprets virtually all complex written forms critically","listening":"understands rapid natural speech across varieties with adjustment","writing":"creates precise nuanced text for sophisticated purposes","speaking":"expresses subtle distinctions spontaneously and coherently"}','Performance may still vary by specialist knowledge and context.'),
('German','A1','CEFR','{"reading":"versteht vertraute Wörter und sehr kurze Texte","listening":"erkennt langsam gesprochene elementare Wendungen","writing":"schreibt kurze persönliche Angaben","speaking":"verwendet einfache gelernte Ausdrücke mit Hilfe"}','Keine Aussage über selbstständige Kommunikation in unbekannten Situationen.'),
('German','A2','CEFR','{"reading":"versteht kurze vorhersehbare Alltagstexte","listening":"versteht häufige Informationen zu unmittelbaren Bedürfnissen","writing":"schreibt kurze verbundene Mitteilungen","speaking":"bewältigt einfache routinemäßige Gespräche"}','Komplexe Erklärungen liegen außerhalb dieses Niveaus.'),
('German','B1','CEFR','{"reading":"versteht klare Sachtexte zu vertrauten Themen","listening":"folgt klarer Standardsprache in vertrauten Bereichen","writing":"verfasst zusammenhängende Texte und begründet Meinungen","speaking":"bewältigt typische Reise-, Lern- und Arbeitssituationen"}','Fachsprache und nuancierte Argumentation benötigen weitere Evidenz.'),
('German','B2','CEFR','{"reading":"versteht komplexe Sach- und Argumentationstexte","listening":"folgt längerem klar gegliedertem Diskurs","writing":"entwickelt strukturierte Argumente mit Details","speaking":"interagiert flüssig und begründet Standpunkte"}','Spezialisierte Kontexte benötigen zusätzliche Aufgaben.'),
('German','C1','CEFR','{"reading":"versteht anspruchsvolle Texte und implizite Bedeutung","listening":"folgt komplexem Diskurs auch ohne deutliche Gliederung","writing":"verfasst detaillierte, stilistisch kontrollierte Texte","speaking":"verwendet Sprache flexibel in Studium und Beruf"}','Keine automatische Gleichsetzung mit muttersprachlicher Kompetenz.'),
('German','C2','CEFR','{"reading":"interpretiert nahezu alle komplexen Textsorten kritisch","listening":"versteht schnelles natürliches Sprechen in vielen Varietäten","writing":"formuliert präzise und nuanciert für anspruchsvolle Zwecke","speaking":"drückt feine Bedeutungsunterschiede spontan aus"}','Leistung bleibt vom Fachwissen und Kontext abhängig.'),
('Japanese','N5','JLPT + KLI extension','{"language_knowledge":"recognizes basic kana, kanji, vocabulary, and sentence patterns","reading":"understands typical short basic sentences","listening":"understands short slow conversations about daily life","productive_extension":"provides very short supported personal responses"}','JLPT itself does not assess speaking or writing; KLI productive evidence is separate.'),
('Japanese','N4','JLPT + KLI extension','{"language_knowledge":"uses basic vocabulary, kanji, and common grammar","reading":"understands passages on familiar daily topics","listening":"follows slow everyday conversations","productive_extension":"produces short connected responses on familiar matters"}','KLI productive evidence must not be reported as an official JLPT component.'),
('Japanese','N3','JLPT + KLI extension','{"language_knowledge":"handles intermediate vocabulary, kanji, and grammar","reading":"understands everyday materials and summaries of more difficult texts","listening":"follows coherent everyday speech near natural speed","productive_extension":"explains familiar experiences and opinions"}','N3 is a bridge level; domain and interaction demands may vary.'),
('Japanese','N2','JLPT + KLI extension','{"language_knowledge":"handles broad vocabulary, kanji, and complex grammar","reading":"understands articles and commentaries on general topics","listening":"follows coherent speech at near-natural speed across settings","productive_extension":"communicates structured views in study and work contexts"}','Productive KLI ratings are not official JLPT scores.'),
('Japanese','N1','JLPT + KLI extension','{"language_knowledge":"interprets advanced vocabulary, kanji, grammar, and nuance","reading":"understands logically complex and abstract writing","listening":"follows natural-speed coherent discourse across contexts","productive_extension":"discusses abstract issues with precision and appropriate register"}','N1 receptive performance does not by itself establish professional productive mastery.');
